create extension if not exists pgcrypto;
create table public.intake_entries (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, description text not null, portion text not null, consumed_at timestamptz not null, entry_type text not null check(entry_type in ('food','alcohol','food_and_alcohol','non_caloric_beverage')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.nutrition_analyses (id uuid primary key default gen_random_uuid(), entry_id uuid not null references public.intake_entries(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, calories numeric, protein_g numeric, carbs_g numeric, fat_g numeric, fiber_g numeric, sugar_g numeric, added_sugar_g numeric, sodium_mg numeric, potassium_mg numeric, calcium_mg numeric, iron_mg numeric, magnesium_mg numeric, vitamin_a_pct numeric, vitamin_b6_pct numeric, vitamin_b12_pct numeric, vitamin_c_pct numeric, vitamin_d_pct numeric, vitamin_e_pct numeric, vitamin_k_pct numeric, folate_pct numeric, confidence text check(confidence in ('high','medium','low')), analysis_json jsonb not null default '{}'::jsonb, created_at timestamptz default now());
create table public.alcohol_analyses (id uuid primary key default gen_random_uuid(), entry_id uuid not null references public.intake_entries(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, beverage_type text, quantity numeric, serving_oz numeric, abv numeric, standard_drinks numeric, alcohol_calories numeric, created_at timestamptz default now());
create table public.bac_readings (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, bac numeric not null check(bac>=0 and bac<=1), measured_at timestamptz not null default now(), related_entry_id uuid references public.intake_entries(id) on delete set null, created_at timestamptz default now());
create table public.bac_reminders (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, related_entry_id uuid not null references public.intake_entries(id) on delete cascade, next_reminder_at timestamptz not null, last_sent_at timestamptz, status text not null default 'active' check(status in ('active','completed','dismissed')), created_at timestamptz default now());
create index intake_entries_user_time_idx on public.intake_entries(user_id, consumed_at desc);
create index bac_readings_user_time_idx on public.bac_readings(user_id, measured_at desc);
create index bac_reminders_due_idx on public.bac_reminders(status,next_reminder_at);
alter table public.intake_entries enable row level security; alter table public.nutrition_analyses enable row level security; alter table public.alcohol_analyses enable row level security; alter table public.bac_readings enable row level security; alter table public.bac_reminders enable row level security;
do $$ declare t text; begin foreach t in array array['intake_entries','nutrition_analyses','alcohol_analyses','bac_readings','bac_reminders'] loop execute format('create policy %I on public.%I for all to authenticated using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id)', t||'_own_rows', t); end loop; end $$;
grant select,insert,update,delete on public.intake_entries,public.nutrition_analyses,public.alcohol_analyses,public.bac_readings,public.bac_reminders to authenticated;